const body = $input.item.json.body || $input.item.json;
const text = body.text || '';

// Extraer números
const regex = /-?\d+(\.\d+)?/g;
const matches = text.match(regex);

if (!matches || matches.length === 0) {
  return {
    json: {
      error: 'No se encontraron números en el texto proporcionado.'
    }
  };
}

const numbers = matches.map(Number);

// 1. Cálculos Estadísticos (Nuevas Capas)
const maximo = Math.max(...numbers);
const minimo = Math.min(...numbers);
const suma = Number(numbers.reduce((a, b) => a + b, 0).toFixed(2));
const promedio = Number((suma / numbers.length).toFixed(2));
const cantidad = numbers.length;

// 2. Ordenamiento y Filtrado
const lista_desc = [...numbers].sort((a, b) => b - a);
const lista_asc = [...numbers].sort((a, b) => a - b);

// 3. Categorización
const positivos = numbers.filter(n => n >= 0).sort((a, b) => b - a);
const negativos = numbers.filter(n => n < 0).sort((a, b) => a - b);

return {
  json: {
    maximo,
    minimo,
    promedio,
    suma,
    cantidad,
    lista_desc,
    lista_asc,
    positivos,
    negativos
  }
};
